# Hindi / Gujarati for Class 10 Maths Ch 9 questions.json
from tr_ch04_common import by_option, feedback, steps

Q = {}
def add(key, question=None, step_overrides=None, **fields):
    iid = f"ch09.q.{key}"
    if question: Q[f"{iid}.question"] = question
    if step_overrides is not None: Q[f"{iid}.answer_steps"] = steps(iid, step_overrides)
    for f, v in fields.items(): Q[f"{iid}.{f}"] = v

add("ex9_1.q1", ("सर्कस का एक कलाकार एक 20 m लंबी डोर पर चढ़ रहा है जो अच्छी तरह से तनी हुई है और भूमि पर सीधे लगे खंभे के शिखर से बँधी हुई है। यदि भूमि स्तर के साथ डोर द्वारा बनाया गया कोण $30^\\circ$ का हो, तो खंभे की ऊँचाई ज्ञात कीजिए।",
                 "સર્કસનો એક કલાકાર 20 m લાંબા દોરડા પર ચડી રહ્યો છે, જે બરાબર તાણીને જમીન પર ઊભા થાંભલાની ટોચ સાથે બાંધેલું છે. જો દોરડું જમીન સાથે $30^\\circ$ નો ખૂણો બનાવે, તો થાંભલાની ઊંચાઈ શોધો."),
    {0: ("डोर तिरछी भुजा है: $\\sin 30^\\circ = \\dfrac{h}{20}$।", "દોરડું ત્રાંસી બાજુ છે: $\\sin 30^\\circ = \\dfrac{h}{20}$."), 2: ("खंभा 10 m ऊँचा है।", "થાંભલો 10 m ઊંચો છે.")})
add("ex9_1.q2", ("आँधी आने से एक पेड़ टूट जाता है और टूटा हुआ भाग इस तरह मुड़ जाता है कि पेड़ का शिखर ज़मीन को छूने लगता है और इसके साथ $30^\\circ$ का कोण बनाता है। पेड़ के पाद-बिंदु की दूरी, जहाँ पेड़ का शिखर ज़मीन को छूता है, 8 m है। पेड़ की ऊँचाई ज्ञात कीजिए।",
                 "વાવાઝોડાથી એક વૃક્ષ તૂટી જાય છે અને તૂટેલો ભાગ એ રીતે વળે છે કે વૃક્ષની ટોચ જમીનને અડે છે અને તેની સાથે $30^\\circ$ નો ખૂણો બનાવે છે. વૃક્ષના તળિયાથી, જ્યાં ટોચ જમીનને અડે છે તે બિંદુનું અંતર 8 m છે. વૃક્ષની ઊંચાઈ શોધો."),
    {0: ("खड़ा भाग: $\\tan 30^\\circ = \\dfrac{a}{8}$, अतः $a = \\dfrac{8}{\\sqrt{3}}$।", "ઊભો ભાગ: $\\tan 30^\\circ = \\dfrac{a}{8}$, તેથી $a = \\dfrac{8}{\\sqrt{3}}$."),
     1: ("टूटा भाग: $\\cos 30^\\circ = \\dfrac{8}{b}$, अतः $b = \\dfrac{16}{\\sqrt{3}}$।", "તૂટેલો ભાગ: $\\cos 30^\\circ = \\dfrac{8}{b}$, તેથી $b = \\dfrac{16}{\\sqrt{3}}$."),
     2: ("ऊँचाई $= a + b = \\dfrac{24}{\\sqrt{3}} = 8\\sqrt{3}$ m", "ઊંચાઈ $= a + b = \\dfrac{24}{\\sqrt{3}} = 8\\sqrt{3}$ m")})
add("ex9_1.q3", ("एक ठेकेदार बच्चों को खेलने के लिए एक पार्क में दो फिसलनपट्टी लगाना चाहती है। 5 वर्ष से कम उम्र के बच्चों के लिए वह ऐसी फिसलनपट्टी लगाना चाहती है जिसका शिखर 1.5 m की ऊँचाई पर हो और भूमि के साथ $30^\\circ$ के कोण पर झुका हुआ हो, जबकि इससे अधिक उम्र के बच्चों के लिए वह 3 m की ऊँचाई पर एक अधिक ढाल की फिसलनपट्टी लगाना चाहती है, जो भूमि के साथ $60^\\circ$ का कोण बनाती हो। प्रत्येक स्थिति में फिसलनपट्टी की लंबाई क्या होनी चाहिए?",
                 "એક કોન્ટ્રાક્ટર બાળકોને રમવા માટે બગીચામાં બે લપસણી મૂકવા માંગે છે. 5 વર્ષથી નાનાં બાળકો માટે તે એવી લપસણી ઇચ્છે છે જેની ટોચ 1.5 m ઊંચાઈએ હોય અને જમીન સાથે $30^\\circ$ ના ખૂણે ઢળેલી હોય, જ્યારે મોટાં બાળકો માટે તે 3 m ઊંચાઈએ વધુ ઢાળવાળી લપસણી ઇચ્છે છે, જે જમીન સાથે $60^\\circ$ નો ખૂણો બનાવે. દરેક કિસ્સામાં લપસણીની લંબાઈ કેટલી હોવી જોઈએ?"),
    {0: ("छोटी फिसलनपट्टी: $\\sin 30^\\circ = \\dfrac{1.5}{L_1}$, अतः $L_1 = 3$ m।", "નાની લપસણી: $\\sin 30^\\circ = \\dfrac{1.5}{L_1}$, તેથી $L_1 = 3$ m."),
     1: ("बड़ी फिसलनपट्टी: $\\sin 60^\\circ = \\dfrac{3}{L_2}$, अतः $L_2 = \\dfrac{6}{\\sqrt{3}}$।", "મોટી લપસણી: $\\sin 60^\\circ = \\dfrac{3}{L_2}$, તેથી $L_2 = \\dfrac{6}{\\sqrt{3}}$.")})
add("ex9_1.q4", ("भूमि के एक बिंदु से, जो मीनार के पाद-बिंदु से 30 m की दूरी पर है, मीनार के शिखर का उन्नयन कोण $30^\\circ$ है। मीनार की ऊँचाई ज्ञात कीजिए।", "જમીન પરના એક બિંદુથી, જે ટાવરના તળિયાથી 30 m દૂર છે, ટાવરની ટોચનો ઉત્સેધકોણ $30^\\circ$ છે. ટાવરની ઊંચાઈ શોધો."),
    {2: ("मीनार $10\\sqrt{3}$ m ऊँची है।", "ટાવર $10\\sqrt{3}$ m ઊંચો છે.")})
add("ex9_1.q5", ("भूमि से 60 m की ऊँचाई पर एक पतंग उड़ रही है। पतंग में लगी डोरी को अस्थायी रूप से भूमि के एक बिंदु से बाँध दिया गया है। भूमि के साथ डोरी का झुकाव $60^\\circ$ है। यह मानकर कि डोरी में कोई ढील नहीं है, डोरी की लंबाई ज्ञात कीजिए।",
                 "જમીનથી 60 m ઊંચાઈએ એક પતંગ ઊડી રહ્યો છે. પતંગની દોરી જમીન પરના એક બિંદુ સાથે થોડા સમય માટે બાંધેલી છે. જમીન સાથે દોરીનો ઢાળ $60^\\circ$ છે. દોરીમાં ઢીલ નથી એમ માની, દોરીની લંબાઈ શોધો."),
    {0: ("डोरी तिरछी भुजा है: $\\sin 60^\\circ = \\dfrac{60}{L}$।", "દોરી ત્રાંસી બાજુ છે: $\\sin 60^\\circ = \\dfrac{60}{L}$."), 2: ("डोरी $40\\sqrt{3}$ m लंबी है।", "દોરી $40\\sqrt{3}$ m લાંબી છે.")})
add("ex9_1.q6", ("1.5 m लंबा एक लड़का 30 m ऊँचे एक भवन से कुछ दूरी पर खड़ा है। जब वह ऊँचे भवन की ओर जाता है, तब उसकी आँख से भवन के शिखर का उन्नयन कोण $30^\\circ$ से $60^\\circ$ हो जाता है। बताइए कि वह भवन की ओर कितनी दूरी तक चलकर गया है।",
                 "1.5 m ઊંચો એક છોકરો 30 m ઊંચા મકાનથી થોડા અંતરે ઊભો છે. જેમ તે મકાન તરફ ચાલે છે, તેમ તેની આંખથી મકાનની ટોચનો ઉત્સેધકોણ $30^\\circ$ થી $60^\\circ$ થાય છે. તે મકાન તરફ કેટલું અંતર ચાલ્યો તે શોધો."),
    {0: ("उसकी आँख से भवन की ऊँचाई $= 30 - 1.5 = 28.5$ m।", "તેની આંખથી ઉપર મકાનની ઊંચાઈ $= 30 - 1.5 = 28.5$ m."),
     1: ("पहले: $\\tan 30^\\circ = \\dfrac{28.5}{d_1}$, अतः $d_1 = 28.5\\sqrt{3}$।", "પહેલાં: $\\tan 30^\\circ = \\dfrac{28.5}{d_1}$, તેથી $d_1 = 28.5\\sqrt{3}$."),
     2: ("बाद में: $\\tan 60^\\circ = \\dfrac{28.5}{d_2}$, अतः $d_2 = \\dfrac{28.5}{\\sqrt{3}}$।", "પછી: $\\tan 60^\\circ = \\dfrac{28.5}{d_2}$, તેથી $d_2 = \\dfrac{28.5}{\\sqrt{3}}$."),
     3: ("चली गई दूरी $= 28.5\\left(\\sqrt{3} - \\dfrac{1}{\\sqrt{3}}\\right) = \\dfrac{57}{\\sqrt{3}}$", "ચાલેલું અંતર $= 28.5\\left(\\sqrt{3} - \\dfrac{1}{\\sqrt{3}}\\right) = \\dfrac{57}{\\sqrt{3}}$")})
Q["ch09.q.ex9_1.q6.figure.title"] = ("लड़का P से Q तक चलता है", "છોકરો P થી Q સુધી ચાલે છે")
add("ex9_1.q7", ("भूमि के एक बिंदु से एक 20 m ऊँचे भवन के शिखर पर लगी एक संचार मीनार के तल और शिखर के उन्नयन कोण क्रमशः $45^\\circ$ और $60^\\circ$ हैं। मीनार की ऊँचाई ज्ञात कीजिए।",
                 "જમીન પરના એક બિંદુથી 20 m ઊંચા મકાનની ટોચ પર લગાવેલા સંચાર ટાવરના તળિયા અને ટોચના ઉત્સેધકોણ અનુક્રમે $45^\\circ$ અને $60^\\circ$ છે. ટાવરની ઊંચાઈ શોધો."),
    {0: ("मीनार का तल: $\\tan 45^\\circ = \\dfrac{20}{d}$, अतः $d = 20$ m।", "ટાવરનું તળિયું: $\\tan 45^\\circ = \\dfrac{20}{d}$, તેથી $d = 20$ m."),
     1: ("मीनार का शिखर: $\\tan 60^\\circ = \\dfrac{20 + t}{20}$, अतः $20 + t = 20\\sqrt{3}$।", "ટાવરની ટોચ: $\\tan 60^\\circ = \\dfrac{20 + t}{20}$, તેથી $20 + t = 20\\sqrt{3}$."),
     2: ("मीनार $20(\\sqrt{3} - 1)$ m ऊँची है।", "ટાવર $20(\\sqrt{3} - 1)$ m ઊંચો છે.")})
add("ex9_1.q8", ("एक पेडस्टल के शिखर पर एक 1.6 m ऊँची मूर्ति लगी है। भूमि के एक बिंदु से मूर्ति के शिखर का उन्नयन कोण $60^\\circ$ है और उसी बिंदु से पेडस्टल के शिखर का उन्नयन कोण $45^\\circ$ है। पेडस्टल की ऊँचाई ज्ञात कीजिए।",
                 "એક પીઠિકાની ટોચ પર 1.6 m ઊંચી મૂર્તિ છે. જમીન પરના એક બિંદુથી મૂર્તિની ટોચનો ઉત્સેધકોણ $60^\\circ$ છે અને તે જ બિંદુથી પીઠિકાની ટોચનો ઉત્સેધકોણ $45^\\circ$ છે. પીઠિકાની ઊંચાઈ શોધો."),
    {0: ("पेडस्टल की ऊँचाई $p$: $\\tan 45^\\circ = \\dfrac{p}{d}$, अतः $d = p$।", "પીઠિકાની ઊંચાઈ $p$: $\\tan 45^\\circ = \\dfrac{p}{d}$, તેથી $d = p$.")})
add("ex9_1.q9", ("एक मीनार के पाद-बिंदु से एक भवन के शिखर का उन्नयन कोण $30^\\circ$ है और भवन के पाद-बिंदु से मीनार के शिखर का उन्नयन कोण $60^\\circ$ है। यदि मीनार 50 m ऊँची हो, तो भवन की ऊँचाई ज्ञात कीजिए।",
                 "ટાવરના તળિયાથી મકાનની ટોચનો ઉત્સેધકોણ $30^\\circ$ છે અને મકાનના તળિયાથી ટાવરની ટોચનો ઉત્સેધકોણ $60^\\circ$ છે. જો ટાવર 50 m ઊંચો હોય, તો મકાનની ઊંચાઈ શોધો."),
    {0: ("भवन के पाद से: $\\tan 60^\\circ = \\dfrac{50}{d}$, अतः $d = \\dfrac{50}{\\sqrt{3}}$।", "મકાનના તળિયેથી: $\\tan 60^\\circ = \\dfrac{50}{d}$, તેથી $d = \\dfrac{50}{\\sqrt{3}}$."),
     1: ("मीनार के पाद से: $\\tan 30^\\circ = \\dfrac{b}{d}$, अतः $b = \\dfrac{50}{\\sqrt{3}} \\times \\dfrac{1}{\\sqrt{3}}$।", "ટાવરના તળિયેથી: $\\tan 30^\\circ = \\dfrac{b}{d}$, તેથી $b = \\dfrac{50}{\\sqrt{3}} \\times \\dfrac{1}{\\sqrt{3}}$.")})
add("ex9_1.q10", ("एक 80 m चौड़ी सड़क के दोनों ओर आमने-सामने समान लंबाई वाले दो खंभे लगे हुए हैं। इन दोनों खंभों के बीच सड़क के एक बिंदु से खंभों के शिखर के उन्नयन कोण क्रमशः $60^\\circ$ और $30^\\circ$ हैं। खंभों की ऊँचाई और खंभों से बिंदु की दूरी ज्ञात कीजिए।",
                  "80 m પહોળા રસ્તાની બંને બાજુ સામસામે સરખી ઊંચાઈના બે થાંભલા છે. બંને થાંભલા વચ્ચે રસ્તા પરના એક બિંદુથી થાંભલાઓની ટોચના ઉત્સેધકોણ અનુક્રમે $60^\\circ$ અને $30^\\circ$ છે. થાંભલાની ઊંચાઈ અને થાંભલાઓથી બિંદુનું અંતર શોધો."),
    {0: ("मान लीजिए बिंदु पहले खंभे से $x$ m और दूसरे से $(80 - x)$ m दूर है; ऊँचाई $h$।", "ધારો કે બિંદુ પહેલા થાંભલાથી $x$ m અને બીજાથી $(80 - x)$ m દૂર છે; ઊંચાઈ $h$."),
     4: ("ऊँचाई $= 20\\sqrt{3}$ m; बिंदु खंभों से 20 m और 60 m दूर है।", "ઊંચાઈ $= 20\\sqrt{3}$ m; બિંદુ થાંભલાઓથી 20 m અને 60 m દૂર છે.")})
Q["ch09.q.ex9_1.q10.figure.title"] = ("80 m चौड़ी सड़क के आर-पार दो बराबर खंभे", "80 m પહોળા રસ્તાની સામસામે બે સરખા થાંભલા")
add("ex9_1.q11", ("एक नहर के एक तट पर एक टीवी टॉवर ऊर्ध्वाधरतः खड़ा है। टॉवर के ठीक सामने दूसरे तट के एक अन्य बिंदु से टॉवर के शिखर का उन्नयन कोण $60^\\circ$ है। इसी तट पर इस बिंदु से 20 m दूर और इस बिंदु को मीनार के पाद से मिलाने वाली रेखा पर स्थित एक अन्य बिंदु से टॉवर के शिखर का उन्नयन कोण $30^\\circ$ है। टॉवर की ऊँचाई और नहर की चौड़ाई ज्ञात कीजिए।",
                  "નહેરના એક કાંઠે એક ટીવી ટાવર ઊભો છે. ટાવરની બરાબર સામે બીજા કાંઠા પરના બિંદુથી ટાવરની ટોચનો ઉત્સેધકોણ $60^\\circ$ છે. આ બિંદુને ટાવરના તળિયા સાથે જોડતી રેખા પર આ બિંદુથી 20 m દૂરના બીજા બિંદુથી ટાવરની ટોચનો ઉત્સેધકોણ $30^\\circ$ છે. ટાવરની ઊંચાઈ અને નહેરની પહોળાઈ શોધો."),
    {0: ("मान लीजिए चौड़ाई $w$ और ऊँचाई $h$ है।", "ધારો કે પહોળાઈ $w$ અને ઊંચાઈ $h$ છે."), 4: ("नहर 10 m चौड़ी है और टॉवर $10\\sqrt{3}$ m ऊँचा है।", "નહેર 10 m પહોળી છે અને ટાવર $10\\sqrt{3}$ m ઊંચો છે.")})
add("ex9_1.q12", ("7 m ऊँचे भवन के शिखर से एक केबल टॉवर के शिखर का उन्नयन कोण $60^\\circ$ है और इसके पाद का अवनमन कोण $45^\\circ$ है। टॉवर की ऊँचाई ज्ञात कीजिए।", "7 m ઊંચા મકાનની ટોચ પરથી એક કેબલ ટાવરની ટોચનો ઉત્સેધકોણ $60^\\circ$ છે અને તેના તળિયાનો અવસેધકોણ $45^\\circ$ છે. ટાવરની ઊંચાઈ શોધો."),
    {0: ("पाद तक अवनमन $45^\\circ$: उनके बीच की दूरी $= 7$ m।", "તળિયા સુધી અવસેધ $45^\\circ$: તેમની વચ્ચેનું અંતર $= 7$ m."),
     1: ("उन्नयन $60^\\circ$: भवन के शिखर से ऊपर टॉवर का भाग $= 7\\tan 60^\\circ = 7\\sqrt{3}$ m।", "ઉત્સેધ $60^\\circ$: મકાનની ટોચથી ઉપર ટાવરનો ભાગ $= 7\\tan 60^\\circ = 7\\sqrt{3}$ m."),
     2: ("टॉवर $7(\\sqrt{3} + 1)$ m ऊँचा है।", "ટાવર $7(\\sqrt{3} + 1)$ m ઊંચો છે.")})
add("ex9_1.q13", ("समुद्र-तल से 75 m ऊँची लाइट हाउस के शिखर से देखने पर दो समुद्री जहाज़ों के अवनमन कोण $30^\\circ$ और $45^\\circ$ हैं। यदि लाइट हाउस के एक ही ओर एक जहाज़ दूसरे जहाज़ के ठीक पीछे हो, तो दोनों जहाज़ों के बीच की दूरी ज्ञात कीजिए।",
                  "દરિયાની સપાટીથી 75 m ઊંચી દીવાદાંડીની ટોચ પરથી જોતાં બે વહાણના અવસેધકોણ $30^\\circ$ અને $45^\\circ$ છે. જો દીવાદાંડીની એક જ બાજુએ એક વહાણ બીજાની બરાબર પાછળ હોય, તો બંને વહાણ વચ્ચેનું અંતર શોધો."),
    {0: ("निकट वाला जहाज़ (अवनमन $45^\\circ$): $\\tan 45^\\circ = \\dfrac{75}{d_1}$, अतः $d_1 = 75$ m।", "નજીકનું વહાણ (અવસેધ $45^\\circ$): $\\tan 45^\\circ = \\dfrac{75}{d_1}$, તેથી $d_1 = 75$ m."),
     1: ("दूर वाला जहाज़ (अवनमन $30^\\circ$): $\\tan 30^\\circ = \\dfrac{75}{d_2}$, अतः $d_2 = 75\\sqrt{3}$ m।", "દૂરનું વહાણ (અવસેધ $30^\\circ$): $\\tan 30^\\circ = \\dfrac{75}{d_2}$, તેથી $d_2 = 75\\sqrt{3}$ m."),
     2: ("जहाज़ों के बीच की दूरी $= d_2 - d_1$", "વહાણો વચ્ચેનું અંતર $= d_2 - d_1$")})
Q["ch09.q.ex9_1.q13.figure.title"] = ("लाइट हाउस से दिखते दो जहाज़", "દીવાદાંડી પરથી દેખાતાં બે વહાણ")
add("ex9_1.q14", ("1.2 m लंबी एक लड़की भूमि से 88.2 m की ऊँचाई पर एक क्षैतिज रेखा में हवा में उड़ रहे गुब्बारे को देखती है। किसी भी क्षण लड़की की आँख से गुब्बारे का उन्नयन कोण $60^\\circ$ है। कुछ समय बाद उन्नयन कोण घटकर $30^\\circ$ हो जाता है। इस अंतराल के दौरान गुब्बारे द्वारा तय की गई दूरी ज्ञात कीजिए।",
                  "1.2 m ઊંચી એક છોકરી જમીનથી 88.2 m ઊંચાઈએ સમક્ષિતિજ રેખામાં પવન સાથે ઊડતો ફુગ્ગો જુએ છે. કોઈ ક્ષણે છોકરીની આંખથી ફુગ્ગાનો ઉત્સેધકોણ $60^\\circ$ છે. થોડા સમય પછી ઉત્સેધકોણ ઘટીને $30^\\circ$ થાય છે. આ સમયગાળામાં ફુગ્ગાએ કાપેલું અંતર શોધો."),
    {0: ("उसकी आँख से ऊपर गुब्बारे की ऊँचाई $= 88.2 - 1.2 = 87$ m।", "તેની આંખથી ઉપર ફુગ્ગાની ઊંચાઈ $= 88.2 - 1.2 = 87$ m."),
     1: ("पहले: $\\tan 60^\\circ = \\dfrac{87}{d_1}$, अतः $d_1 = \\dfrac{87}{\\sqrt{3}} = 29\\sqrt{3}$।", "પહેલાં: $\\tan 60^\\circ = \\dfrac{87}{d_1}$, તેથી $d_1 = \\dfrac{87}{\\sqrt{3}} = 29\\sqrt{3}$."),
     2: ("बाद में: $\\tan 30^\\circ = \\dfrac{87}{d_2}$, अतः $d_2 = 87\\sqrt{3}$।", "પછી: $\\tan 30^\\circ = \\dfrac{87}{d_2}$, તેથી $d_2 = 87\\sqrt{3}$."),
     3: ("तय की गई दूरी $= 87\\sqrt{3} - 29\\sqrt{3}$", "કાપેલું અંતર $= 87\\sqrt{3} - 29\\sqrt{3}$")})
add("ex9_1.q15", ("एक सीधा राजमार्ग एक मीनार के पाद तक जाता है। मीनार के शिखर पर खड़ा एक आदमी एक कार को $30^\\circ$ के अवनमन कोण पर देखता है, जो कि मीनार के पाद की ओर एक समान चाल से जाता है। छः सेकंड बाद कार का अवनमन कोण $60^\\circ$ हो गया। इस बिंदु से मीनार के पाद तक पहुँचने में कार द्वारा लिया गया समय ज्ञात कीजिए।",
                  "એક સીધો ધોરીમાર્ગ ટાવરના તળિયા સુધી જાય છે. ટાવરની ટોચ પર ઊભેલો માણસ એક કારને $30^\\circ$ ના અવસેધકોણે જુએ છે, જે ટાવરના તળિયા તરફ એકસરખી ઝડપે આવે છે. છ સેકન્ડ પછી કારનો અવસેધકોણ $60^\\circ$ થાય છે. આ બિંદુથી ટાવરના તળિયા સુધી પહોંચવામાં કારને લાગતો સમય શોધો."),
    {0: ("मान लीजिए मीनार $h$ ऊँची है। पहले कार $\\sqrt{3}h$ दूर है (अवनमन $30^\\circ$)।", "ધારો કે ટાવર $h$ ઊંચો છે. પહેલાં કાર $\\sqrt{3}h$ દૂર છે (અવસેધ $30^\\circ$)."),
     1: ("छः सेकंड बाद वह $\\dfrac{h}{\\sqrt{3}}$ दूर है (अवनमन $60^\\circ$)।", "છ સેકન્ડ પછી તે $\\dfrac{h}{\\sqrt{3}}$ દૂર છે (અવસેધ $60^\\circ$)."),
     2: ("6 s में तय दूरी $= \\sqrt{3}h - \\dfrac{h}{\\sqrt{3}} = \\dfrac{2h}{\\sqrt{3}}$।", "6 s માં કાપેલું અંતર $= \\sqrt{3}h - \\dfrac{h}{\\sqrt{3}} = \\dfrac{2h}{\\sqrt{3}}$."),
     3: ("शेष दूरी $\\dfrac{h}{\\sqrt{3}}$ इसकी आधी है।", "બાકીનું અંતર $\\dfrac{h}{\\sqrt{3}}$ તેનું અડધું છે."), 4: ("उसी चाल से इसमें 3 सेकंड लगते हैं।", "એ જ ઝડપે તેમાં 3 સેકન્ડ લાગે છે.")})
# NCERT examples
add("eg_tower", ("भूमि पर एक मीनार ऊर्ध्वाधरतः खड़ी है। भूमि के एक बिंदु से, जो मीनार के पाद-बिंदु से 15 m दूर है, मीनार के शिखर का उन्नयन कोण $60^\\circ$ है। मीनार की ऊँचाई ज्ञात कीजिए।",
                 "જમીન પર એક ટાવર ઊભો છે. જમીન પરના એક બિંદુથી, જે ટાવરના તળિયાથી 15 m દૂર છે, ટાવરની ટોચનો ઉત્સેધકોણ $60^\\circ$ છે. ટાવરની ઊંચાઈ શોધો."),
    {2: ("मीनार $15\\sqrt{3}$ m ऊँची है।", "ટાવર $15\\sqrt{3}$ m ઊંચો છે.")})
Q["ch09.q.eg_tower.figure.title"] = ("15 m दूर एक मीनार", "15 m દૂર એક ટાવર")
add("eg_chimney", ("1.5 m लंबा एक प्रेक्षक एक चिमनी से 28.5 m की दूरी पर है। उसकी आँखों से चिमनी के शिखर का उन्नयन कोण $45^\\circ$ है। चिमनी की ऊँचाई बताइए।", "1.5 m ઊંચો એક નિરીક્ષક ચીમનીથી 28.5 m દૂર છે. તેની આંખથી ચીમનીની ટોચનો ઉત્સેધકોણ $45^\\circ$ છે. ચીમનીની ઊંચાઈ શોધો."),
    {1: ("चिमनी 30 m ऊँची है।", "ચીમની 30 m ઊંચી છે.")})
add("eg_flagstaff", ("भूमि के एक बिंदु P से 10 m ऊँचे भवन के शिखर का उन्नयन कोण $30^\\circ$ है। भवन के शिखर पर एक ध्वज लहराया गया है और P से ध्वज-दंड के शिखर का उन्नयन कोण $45^\\circ$ है। ध्वज-दंड की लंबाई और बिंदु P से भवन की दूरी ज्ञात कीजिए।",
                     "જમીન પરના બિંદુ P થી 10 m ઊંચા મકાનની ટોચનો ઉત્સેધકોણ $30^\\circ$ છે. મકાનની ટોચ પર ધ્વજ ફરકાવેલો છે અને P થી ધ્વજદંડની ટોચનો ઉત્સેધકોણ $45^\\circ$ છે. ધ્વજદંડની લંબાઈ અને બિંદુ P થી મકાનનું અંતર શોધો."),
    {2: ("ध्वज-दंड $= 10(\\sqrt{3} - 1) \\approx 7.32$ m; दूरी $= 10\\sqrt{3} \\approx 17.32$ m।", "ધ્વજદંડ $= 10(\\sqrt{3} - 1) \\approx 7.32$ m; અંતર $= 10\\sqrt{3} \\approx 17.32$ m.")})
Q["ch09.q.eg_flagstaff.figure.title"] = ("भवन BC और ध्वज-दंड CD", "મકાન BC અને ધ્વજદંડ CD")
add("eg_shadow", ("समतल भूमि पर खड़ी मीनार की छाया उस स्थिति में 40 m अधिक लंबी हो जाती है, जब सूर्य का उन्नतांश $60^\\circ$ से घटकर $30^\\circ$ हो जाता है। मीनार की ऊँचाई ज्ञात कीजिए।",
                  "સમતલ જમીન પર ઊભેલા ટાવરનો પડછાયો, જ્યારે સૂર્યનો ઉત્સેધ $60^\\circ$ થી ઘટીને $30^\\circ$ થાય ત્યારે 40 m વધુ લાંબો થાય છે. ટાવરની ઊંચાઈ શોધો."),
    {1: ("$\\tan 30^\\circ = \\dfrac{h}{x + 40}$, अतः $3x = x + 40$ और $x = 20$।", "$\\tan 30^\\circ = \\dfrac{h}{x + 40}$, તેથી $3x = x + 40$ અને $x = 20$.")})
Q["ch09.q.eg_shadow.figure.title"] = ("छाया 40 m अधिक लंबी है", "પડછાયો 40 m વધુ લાંબો છે")
add("eg_buildings", ("एक बहुमंज़िले भवन के शिखर से देखने पर 8 m ऊँचे भवन के शिखर और तल के अवनमन कोण क्रमशः $30^\\circ$ और $45^\\circ$ हैं। बहुमंज़िले भवन की ऊँचाई और दोनों भवनों के बीच की दूरी ज्ञात कीजिए।",
                     "એક બહુમાળી મકાનની ટોચ પરથી જોતાં 8 m ઊંચા મકાનની ટોચ અને તળિયાના અવસેધકોણ અનુક્રમે $30^\\circ$ અને $45^\\circ$ છે. બહુમાળી મકાનની ઊંચાઈ અને બંને મકાન વચ્ચેનું અંતર શોધો."),
    {0: ("मान लीजिए बहुमंज़िले भवन की ऊँचाई $H$ और भवनों के बीच की दूरी $d$ है।", "ધારો કે બહુમાળી મકાનની ઊંચાઈ $H$ અને મકાનો વચ્ચેનું અંતર $d$ છે."),
     1: ("अवनमन $45^\\circ$: $\\tan 45^\\circ = \\dfrac{H}{d}$, अतः $H = d$।", "અવસેધ $45^\\circ$: $\\tan 45^\\circ = \\dfrac{H}{d}$, તેથી $H = d$."),
     2: ("अवनमन $30^\\circ$: $\\tan 30^\\circ = \\dfrac{H - 8}{d}$, अतः $d - 8 = \\dfrac{d}{\\sqrt{3}}$।", "અવસેધ $30^\\circ$: $\\tan 30^\\circ = \\dfrac{H - 8}{d}$, તેથી $d - 8 = \\dfrac{d}{\\sqrt{3}}$."),
     4: ("ऊँचाई $=$ दूरी $= 4(3 + \\sqrt{3})$ m", "ઊંચાઈ $=$ અંતર $= 4(3 + \\sqrt{3})$ m")})
Q["ch09.q.eg_buildings.figure.title"] = ("एक छोटे भवन को ऊपर से देखना", "નાના મકાનને ઉપરથી જોવું")
add("eg_river", ("एक नदी के पुल के एक बिंदु से नदी के सम्मुख किनारों के अवनमन कोण क्रमशः $30^\\circ$ और $45^\\circ$ हैं। यदि पुल किनारों से 3 m की ऊँचाई पर हो, तो नदी की चौड़ाई ज्ञात कीजिए।",
                 "નદી પરના પુલના એક બિંદુથી નદીના સામસામેના કાંઠાના અવસેધકોણ અનુક્રમે $30^\\circ$ અને $45^\\circ$ છે. જો પુલ કાંઠાથી 3 m ઊંચાઈએ હોય, તો નદીની પહોળાઈ શોધો."),
    {0: ("$45^\\circ$ वाला किनारा: दूरी $= \\dfrac{3}{\\tan 45^\\circ} = 3$ m।", "$45^\\circ$ વાળો કાંઠો: અંતર $= \\dfrac{3}{\\tan 45^\\circ} = 3$ m."),
     1: ("$30^\\circ$ वाला किनारा: दूरी $= \\dfrac{3}{\\tan 30^\\circ} = 3\\sqrt{3}$ m।", "$30^\\circ$ વાળો કાંઠો: અંતર $= \\dfrac{3}{\\tan 30^\\circ} = 3\\sqrt{3}$ m."),
     2: ("चौड़ाई $= 3(\\sqrt{3} + 1)$ m", "પહોળાઈ $= 3(\\sqrt{3} + 1)$ m")})
