add("vsa1", ("6 m ऊँचे एक खंभे की भूमि पर छाया $2\\sqrt{3}$ m लंबी है। सूर्य का उन्नयन कोण ज्ञात कीजिए।", "6 m ઊંચા થાંભલાનો જમીન પર પડછાયો $2\\sqrt{3}$ m લાંબો છે. સૂર્યનો ઉત્સેધકોણ શોધો."))
add("vsa2", ("एक सीढ़ी भूमि से $60^\\circ$ का कोण बनाती है, और इसका पाद दीवार से 2 m दूर है। सीढ़ी की लंबाई ज्ञात कीजिए।", "એક નિસરણી જમીન સાથે $60^\\circ$ નો ખૂણો બનાવે છે, અને તેનો પાયો દીવાલથી 2 m દૂર છે. નિસરણીની લંબાઈ શોધો."))
add("sa1", ("10 m ऊँचे मकान के शिखर से एक मीनार के शिखर का उन्नयन कोण $60^\\circ$ और उसके पाद का अवनमन कोण $30^\\circ$ है। मीनार की ऊँचाई ज्ञात कीजिए।", "10 m ઊંચા મકાનની ટોચ પરથી ટાવરની ટોચનો ઉત્સેધકોણ $60^\\circ$ અને તેના તળિયાનો અવસેધકોણ $30^\\circ$ છે. ટાવરની ઊંચાઈ શોધો."),
    {0: ("अवनमन $30^\\circ$: दूरी $= \\dfrac{10}{\\tan 30^\\circ} = 10\\sqrt{3}$ m।", "અવસેધ $30^\\circ$: અંતર $= \\dfrac{10}{\\tan 30^\\circ} = 10\\sqrt{3}$ m."),
     1: ("उन्नयन $60^\\circ$: मकान के शिखर से ऊपर की ऊँचाई $= 10\\sqrt{3} \\times \\sqrt{3} = 30$ m।", "ઉત્સેધ $60^\\circ$: મકાનની ટોચથી ઉપરની ઊંચાઈ $= 10\\sqrt{3} \\times \\sqrt{3} = 30$ m."),
     2: ("मीनार $= 30 + 10 = 40$ m", "ટાવર $= 30 + 10 = 40$ m")})
add("sa2", ("एक मीनार के पाद से एक पहाड़ी के शिखर का उन्नयन कोण $60^\\circ$ है और पहाड़ी के पाद से मीनार के शिखर का उन्नयन कोण $30^\\circ$ है। यदि मीनार 50 m ऊँची है, तो पहाड़ी की ऊँचाई ज्ञात कीजिए।", "ટાવરના તળિયાથી ટેકરીની ટોચનો ઉત્સેધકોણ $60^\\circ$ છે અને ટેકરીના તળિયાથી ટાવરની ટોચનો ઉત્સેધકોણ $30^\\circ$ છે. જો ટાવર 50 m ઊંચો હોય, તો ટેકરીની ઊંચાઈ શોધો."),
    {0: ("पहाड़ी के पाद से: $\\tan 30^\\circ = \\dfrac{50}{d}$, अतः $d = 50\\sqrt{3}$ m।", "ટેકરીના તળિયેથી: $\\tan 30^\\circ = \\dfrac{50}{d}$, તેથી $d = 50\\sqrt{3}$ m."),
     1: ("मीनार के पाद से: $\\tan 60^\\circ = \\dfrac{H}{50\\sqrt{3}}$", "ટાવરના તળિયેથી: $\\tan 60^\\circ = \\dfrac{H}{50\\sqrt{3}}$")})
add("sa3", ("जब सूर्य का उन्नतांश $60^\\circ$ के स्थान पर $45^\\circ$ होता है, तो एक मीनार की छाया 20 m अधिक लंबी होती है। मीनार की ऊँचाई ज्ञात कीजिए।", "જ્યારે સૂર્યનો ઉત્સેધ $60^\\circ$ ને બદલે $45^\\circ$ હોય, ત્યારે ટાવરનો પડછાયો 20 m વધુ લાંબો હોય છે. ટાવરની ઊંચાઈ શોધો."),
    {0: ("छोटी छाया: $\\dfrac{h}{\\sqrt{3}}$; लंबी छाया: $h$।", "નાનો પડછાયો: $\\dfrac{h}{\\sqrt{3}}$; લાંબો પડછાયો: $h$.")})
add("la1", ("दो जहाज़ एक लाइट हाउस के विपरीत ओर उसके पाद की सीध में हैं। 100 m ऊँचे लाइट हाउस के शिखर से दोनों जहाज़ों के अवनमन कोण $45^\\circ$ और $30^\\circ$ हैं। जहाज़ों के बीच की दूरी ज्ञात कीजिए। ($\\sqrt{3} = 1.732$ लीजिए)", "બે વહાણ દીવાદાંડીની સામસામી બાજુએ તેના તળિયાની સીધમાં છે. 100 m ઊંચી દીવાદાંડીની ટોચ પરથી બંને વહાણના અવસેધકોણ $45^\\circ$ અને $30^\\circ$ છે. વહાણો વચ્ચેનું અંતર શોધો. ($\\sqrt{3} = 1.732$ લો)"),
    {0: ("मान लीजिए लाइट हाउस $AB = 100$ m है, और जहाज़ दोनों ओर $C$ और $D$ पर हैं।", "ધારો કે દીવાદાંડી $AB = 100$ m છે, અને વહાણ બંને બાજુએ $C$ અને $D$ પર છે."),
     3: ("दूरी $= BC + BD = 100(1 + \\sqrt{3})$", "અંતર $= BC + BD = 100(1 + \\sqrt{3})$")})
add("la2", ("भूमि के एक बिंदु से एक जेट विमान का उन्नयन कोण $60^\\circ$ है। 15 सेकंड की उड़ान के बाद उन्नयन कोण $30^\\circ$ हो जाता है। यदि जेट $1500\\sqrt{3}$ m की अचर ऊँचाई पर उड़ रहा है, तो जेट की चाल km/h में ज्ञात कीजिए।", "જમીન પરના એક બિંદુથી જેટ વિમાનનો ઉત્સેધકોણ $60^\\circ$ છે. 15 સેકન્ડની ઉડાન પછી ઉત્સેધકોણ $30^\\circ$ થાય છે. જો જેટ $1500\\sqrt{3}$ m ની અચળ ઊંચાઈએ ઊડતું હોય, તો જેટની ઝડપ km/h માં શોધો."),
    {0: ("पहली स्थिति: क्षैतिज दूरी $= \\dfrac{1500\\sqrt{3}}{\\tan 60^\\circ} = 1500$ m।", "પ્રથમ સ્થાન: સમક્ષિતિજ અંતર $= \\dfrac{1500\\sqrt{3}}{\\tan 60^\\circ} = 1500$ m."),
     1: ("दूसरी स्थिति: क्षैतिज दूरी $= \\dfrac{1500\\sqrt{3}}{\\tan 30^\\circ} = 4500$ m।", "બીજું સ્થાન: સમક્ષિતિજ અંતર $= \\dfrac{1500\\sqrt{3}}{\\tan 30^\\circ} = 4500$ m."),
     2: ("15 s में तय दूरी $= 3000$ m।", "15 s માં કાપેલું અંતર $= 3000$ m."), 3: ("चाल $= 200$ m/s", "ઝડપ $= 200$ m/s")})
add("sqp38", ("इंडिया गेट (पहले अखिल भारतीय युद्ध स्मारक के नाम से जाना जाता था) नई दिल्ली में कर्तव्य पथ (पहले राजपथ) के निकट स्थित है। यह प्रथम विश्व युद्ध में अपने प्राण देने वाले भारतीय सेना के 74187 सैनिकों के स्मारक के रूप में खड़ा है। 42 m ऊँची इस संरचना को सर एडविन लुटियंस ने रोमन विजय-द्वारों की शैली में डिज़ाइन किया था। 1 m लंबी एक विद्यार्थी श्रेया अपने अध्ययन भ्रमण के दौरान इंडिया गेट गई।\n\n(i) यदि श्रेया इंडिया गेट से 41 m दूर खड़ी है, तो उसकी आँख से इंडिया गेट के शिखर का उन्नयन कोण क्या है? (1)\n\n(ii) यदि श्रेया अपनी आँख से इंडिया गेट के शिखर का उन्नयन कोण $60^\\circ$ देखती है, तो वह इंडिया गेट के आधार से कितनी दूर खड़ी है? (1)\n\n(iii) जब वह अपनी मूल स्थिति से कुछ दूरी पीछे हटती है, तो श्रेया की आँख से उन्नयन कोण $45^\\circ$ से $30^\\circ$ हो जाता है। उसके द्वारा पीछे हटने की दूरी ज्ञात कीजिए। अथवा यदि श्रेया इंडिया गेट से $\\dfrac{41}{\\sqrt{3}}$ m की दूरी वाले बिंदु पर जाती है, तो उसकी आँख द्वारा इंडिया गेट के शिखर पर बनाया गया उन्नयन कोण ज्ञात कीजिए। (2)",
               "ઇન્ડિયા ગેટ (પહેલાં અખિલ ભારતીય યુદ્ધ સ્મારક તરીકે જાણીતો) નવી દિલ્હીમાં કર્તવ્ય પથ (પહેલાં રાજપથ) પાસે આવેલો છે. તે પ્રથમ વિશ્વયુદ્ધમાં પ્રાણ આપનાર ભારતીય સેનાના 74187 સૈનિકોના સ્મારક તરીકે ઊભો છે. 42 m ઊંચી આ રચના સર એડવિન લુટિયન્સે રોમન વિજયદ્વારની શૈલીમાં ડિઝાઇન કરી હતી. 1 m ઊંચી વિદ્યાર્થિની શ્રેયા તેના અભ્યાસ પ્રવાસ દરમિયાન ઇન્ડિયા ગેટ ગઈ.\n\n(i) જો શ્રેયા ઇન્ડિયા ગેટથી 41 m દૂર ઊભી હોય, તો તેની આંખથી ઇન્ડિયા ગેટની ટોચનો ઉત્સેધકોણ કેટલો છે? (1)\n\n(ii) જો શ્રેયા તેની આંખથી ઇન્ડિયા ગેટની ટોચનો ઉત્સેધકોણ $60^\\circ$ જુએ, તો તે ઇન્ડિયા ગેટના પાયાથી કેટલી દૂર ઊભી છે? (1)\n\n(iii) જ્યારે તે મૂળ સ્થાનેથી થોડું પાછળ ખસે છે, ત્યારે શ્રેયાની આંખથી ઉત્સેધકોણ $45^\\circ$ થી $30^\\circ$ થાય છે. તે કેટલું પાછળ ખસી તે શોધો. અથવા જો શ્રેયા ઇન્ડિયા ગેટથી $\\dfrac{41}{\\sqrt{3}}$ m દૂરના બિંદુએ જાય, તો તેની આંખથી ઇન્ડિયા ગેટની ટોચનો ઉત્સેધકોણ શોધો. (2)"),
    {0: ("उसकी आँख से ऊपर इंडिया गेट की ऊँचाई $= 42 - 1 = 41$ m।", "તેની આંખથી ઉપર ઇન્ડિયા ગેટની ઊંચાઈ $= 42 - 1 = 41$ m."),
     1: ("(i) $\\tan \\theta = \\dfrac{41}{41} = 1$, अतः कोण $45^\\circ$ है।", "(i) $\\tan \\theta = \\dfrac{41}{41} = 1$, તેથી ખૂણો $45^\\circ$ છે."),
     2: ("(ii) $\\tan 60^\\circ = \\dfrac{41}{x}$, अतः $x = \\dfrac{41}{\\sqrt{3}}$ m।", "(ii) $\\tan 60^\\circ = \\dfrac{41}{x}$, તેથી $x = \\dfrac{41}{\\sqrt{3}}$ m."),
     3: ("(iii) $\\tan 30^\\circ = \\dfrac{41}{41 + x}$ से $41 + x = 41\\sqrt{3}$, अतः वह $41(\\sqrt{3} - 1)$ m पीछे हटती है। अथवा $\\tan \\theta = \\dfrac{41}{41/\\sqrt{3}} = \\sqrt{3}$, अतः $\\theta = 60^\\circ$।",
         "(iii) $\\tan 30^\\circ = \\dfrac{41}{41 + x}$ પરથી $41 + x = 41\\sqrt{3}$, તેથી તે $41(\\sqrt{3} - 1)$ m પાછળ ખસે છે. અથવા $\\tan \\theta = \\dfrac{41}{41/\\sqrt{3}} = \\sqrt{3}$, તેથી $\\theta = 60^\\circ$.")})
Q["ch09.q.sqp38.figure.title"] = ("श्रेया और इंडिया गेट (आँख के स्तर से ऊपर)", "શ્રેયા અને ઇન્ડિયા ગેટ (આંખના સ્તરથી ઉપર)")
add("cb2", ("एक लाइट हाउस 60 m ऊँचा है। उसके शिखर से एक रक्षक एक नाव को $30^\\circ$ के अवनमन कोण पर देखता है। नाव सीधे लाइट हाउस की ओर चलती है, और बाद में अवनमन कोण $60^\\circ$ हो जाता है।\n\n(i) पहले नाव लाइट हाउस से कितनी दूर थी? (1)\n\n(ii) बाद में यह लाइट हाउस से कितनी दूर है? (1)\n\n(iii) नाव ने कितनी दूरी तय की? अथवा यदि नाव $2\\sqrt{3}$ m/s की चाल से चलती है, तो इसमें कितना समय लगा? (2)",
             "એક દીવાદાંડી 60 m ઊંચી છે. તેની ટોચ પરથી એક ચોકીદાર હોડીને $30^\\circ$ ના અવસેધકોણે જુએ છે. હોડી સીધી દીવાદાંડી તરફ આવે છે, અને પછી અવસેધકોણ $60^\\circ$ થાય છે.\n\n(i) પહેલાં હોડી દીવાદાંડીથી કેટલી દૂર હતી? (1)\n\n(ii) પછી તે દીવાદાંડીથી કેટલી દૂર છે? (1)\n\n(iii) હોડીએ કેટલું અંતર કાપ્યું? અથવા જો હોડી $2\\sqrt{3}$ m/s ની ઝડપે ચાલે, તો કેટલો સમય લાગ્યો? (2)"),
    {2: ("(iii) $60\\sqrt{3} - 20\\sqrt{3} = 40\\sqrt{3}$ m। अथवा समय $= \\dfrac{40\\sqrt{3}}{2\\sqrt{3}} = 20$ s", "(iii) $60\\sqrt{3} - 20\\sqrt{3} = 40\\sqrt{3}$ m. અથવા સમય $= \\dfrac{40\\sqrt{3}}{2\\sqrt{3}} = 20$ s")})

AR = {
 "ch09.q.ar1": ("यदि किसी खंभे की छाया उसकी ऊँचाई के बराबर हो, तो सूर्य का उन्नयन कोण $45^\\circ$ है।", "$\\tan 45^\\circ = 1$।", "જો થાંભલાનો પડછાયો તેની ઊંચાઈ જેટલો હોય, તો સૂર્યનો ઉત્સેધકોણ $45^\\circ$ છે.", "$\\tan 45^\\circ = 1$.",
                "$\\tan \\theta = \\dfrac{\\text{height}}{\\text{shadow}} = 1$।", "$\\tan 45^\\circ = 1$ ही कोण देता है।", "$\\tan \\theta = \\dfrac{\\text{height}}{\\text{shadow}} = 1$.", "$\\tan 45^\\circ = 1$ જ ખૂણો આપે છે.",
                "$\\tan \\theta = \\dfrac{\\text{height}}{\\text{shadow}} = 1$, और $\\tan 45^\\circ = 1$ से कोण मिलता है।", "$\\tan \\theta = \\dfrac{\\text{height}}{\\text{shadow}} = 1$, અને $\\tan 45^\\circ = 1$ પરથી ખૂણો મળે છે."),
 "ch09.q.ar2": ("मीनार की ओर चलने पर उसके शिखर का उन्नयन कोण बढ़ता है।", "मीनार की ओर चलने पर उसकी ऊँचाई बदलती है।", "ટાવર તરફ ચાલતાં તેની ટોચનો ઉત્સેધકોણ વધે છે.", "ટાવર તરફ ચાલતાં તેની ઊંચાઈ બદલાય છે.",
                "दूरी घटती है जबकि ऊँचाई वही रहती है।", "मीनार की ऊँचाई नहीं बदलती।", "અંતર ઘટે છે જ્યારે ઊંચાઈ એ જ રહે છે.", "ટાવરની ઊંચાઈ બદલાતી નથી.",
                "A सत्य है: दूरी घटती है। R असत्य है: ऊँचाई नहीं बदलती।", "A સાચું છે: અંતર ઘટે છે. R ખોટું છે: ઊંચાઈ બદલાતી નથી."),
 "ch09.q.ar3": ("10 m लंबी सीढ़ी जो दीवार पर 5 m की ऊँचाई तक पहुँचती है, भूमि से $60^\\circ$ का कोण बनाती है।", "$\\sin 30^\\circ = \\dfrac{1}{2}$।", "10 m લાંબી નિસરણી જે દીવાલ પર 5 m ઊંચાઈ સુધી પહોંચે છે, તે જમીન સાથે $60^\\circ$ નો ખૂણો બનાવે છે.", "$\\sin 30^\\circ = \\dfrac{1}{2}$.",
                "$\\sin \\theta = \\dfrac{5}{10} = \\dfrac{1}{2}$ से $30^\\circ$ मिलता है, $60^\\circ$ नहीं।", "$\\sin 30^\\circ = \\dfrac{1}{2}$ एक सही मान है।", "$\\sin \\theta = \\dfrac{5}{10} = \\dfrac{1}{2}$ પરથી $30^\\circ$ મળે છે, $60^\\circ$ નહિ.", "$\\sin 30^\\circ = \\dfrac{1}{2}$ એ સાચી કિંમત છે.",
                "A असत्य है: $\\sin \\theta = \\dfrac{5}{10} = \\dfrac{1}{2}$ से $\\theta = 30^\\circ$। R सत्य है।", "A ખોટું છે: $\\sin \\theta = \\dfrac{5}{10} = \\dfrac{1}{2}$ પરથી $\\theta = 30^\\circ$. R સાચું છે."),
 "ch09.q.ar4": ("$P$ से $Q$ का अवनमन कोण, $Q$ से $P$ के उन्नयन कोण के बराबर है।", "ये समांतर क्षैतिज रेखाओं के बीच एकांतर कोण हैं।", "$P$ થી $Q$ નો અવસેધકોણ એ $Q$ થી $P$ ના ઉત્સેધકોણ જેટલો છે.", "તે સમાંતર સમક્ષિતિજ રેખાઓ વચ્ચેના યુગ્મકોણ છે.",
                "ये समांतर रेखाओं के बीच एकांतर कोण हैं।", "समांतर रेखाओं के बीच एकांतर कोण बराबर होते हैं, ठीक इसी कारण A सत्य है।", "તે સમાંતર રેખાઓ વચ્ચેના યુગ્મકોણ છે.", "સમાંતર રેખાઓ વચ્ચેના યુગ્મકોણ સરખા હોય છે, બરાબર આ જ કારણે A સાચું છે.",
                "समांतर रेखाओं के बीच एकांतर कोण बराबर होते हैं, ठीक इसी कारण A सत्य है।", "સમાંતર રેખાઓ વચ્ચેના યુગ્મકોણ સરખા હોય છે, બરાબર આ જ કારણે A સાચું છે."),
 "ch09.q.ar5": ("20 m दूर स्थित बिंदु से 20 m ऊँची मीनार के शिखर का उन्नयन कोण $45^\\circ$ है।", "अवनमन कोण क्षैतिज से नीचे मापा जाता है।", "20 m દૂરના બિંદુથી 20 m ઊંચા ટાવરની ટોચનો ઉત્સેધકોણ $45^\\circ$ છે.", "અવસેધકોણ સમક્ષિતિજથી નીચે મપાય છે.",
                "$\\tan \\theta = \\dfrac{20}{20} = 1$।", "यह सत्य है, पर यह अवनमन के बारे में है, A के बारे में नहीं।", "$\\tan \\theta = \\dfrac{20}{20} = 1$.", "તે સાચું છે, પણ તે અવસેધ વિશે છે, A વિશે નહિ.",
                "A सत्य है क्योंकि $\\tan \\theta = 1$। R सत्य है पर अवनमन के बारे में है, A के बारे में नहीं।", "A સાચું છે કારણ કે $\\tan \\theta = 1$. R સાચું છે પણ અવસેધ વિશે છે, A વિશે નહિ."),
}
